    "def test_inference_yolo():\n",
    "        total_preds = 0\n",
    "        total_correct = 0\n",
    "        results = model.predict(\n",
    "            # source=\"/kaggle/working/datasets/home_fire/test/images\",\n",
    "            source=\"/kaggle/working/datasets/detectium_real_fire/train/images\",\n",
    "            conf=0.25,\n",
    "            save=True\n",
    "        )\n",
    "        labels_path = \"/kaggle/working/datasets/detectium_real_fire/train/labels\"\n",
    "        # labels_path = \"/kaggle/working/datasets/home_fire/test/labels\"\n",
    "        class_names = model.names\n",
    "        for result in results:\n",
    "            img_path = Path(result.path)\n",
    "            label_file = (\n",
    "                Path(labels_path) / f\"{img_path.stem}.txt\"\n",
    "            )\n",
    "            expected = []\n",
    "            with open(label_file) as f:\n",
    "                for line in f:\n",
    "                    cls = int(line.split()[0])\n",
    "                    expected.append(class_names[cls])\n",
    "\n",
    "\n",
    "            predicted = [\n",
    "                class_names[int(box.cls)]\n",
    "                for box in result.boxes\n",
    "            ]\n",
    "\n",
    "            total_preds += 1\n",
    "            if (set(expected) == set(predicted)):\n",
    "                total_correct +=1\n",
    "            print(img_path.name)\n",
    "            print(\"Expected :\", expected)\n",
    "            print(\"Predicted:\", predicted)\n",
    "        print(\"Total Predictions:\", total_preds, \"Total Correction:\", total_correct, 'Accuracy:', total_correct/total_preds)\n",
    "\n",
    "# test_inference_yolo()"
